-- How many approvals an invoice has at its approved total: a draft whose grand total is more than twice
-- the approval limit needs two. An invoice approved before the count was kept has one approval.
ALTER TABLE invoice ADD COLUMN approvals INT NOT NULL DEFAULT 0;
UPDATE invoice SET approvals = 1 WHERE approved_total IS NOT NULL;
-- The percentage (0 for none) a client's typed recurring prices go up by on each anniversary of the plan.
ALTER TABLE client ADD COLUMN uplift_pct DECIMAL(5, 2) NOT NULL DEFAULT 0;
-- The day a recurring invoice's plan began (moved on a year at each price rise); null when it has none.
ALTER TABLE invoice ADD COLUMN recurring_since DATE;
-- The grand total and tax an invoice was sent with; the invoice is worth exactly that once sent.
-- Null for a draft, or for a sent invoice whose figures were not kept (worth what its lines work out to).
ALTER TABLE invoice ADD COLUMN sent_total DECIMAL(19, 2);
ALTER TABLE invoice ADD COLUMN sent_tax DECIMAL(19, 2);
-- The grand total an invoice was approved at, when it was over the workspace's approval limit; the
-- approval stands while its grand total is not above it. Null while it has not been approved.
ALTER TABLE invoice ADD COLUMN approved_total DECIMAL(19, 2);
170:     * The grand total the invoice was approved at, when it was over the workspace's approval limit;
171:     * null while it has not been approved.
173:    @Column(name = "approved_total")
174:    private BigDecimal approvedTotal;
186:    /** The day the invoice was approved; null while it has not been, or for an approval given before the day was kept. */
187:    @Column(name = "approved_on")
188:    private LocalDate approvedOn;
190:    /** How many approvals the invoice has at its approved total; 0 while it has not been approved. */
191:    @Column(name = "approvals")
192:    private int approvals;
400:     * The approval limit in US dollars, as stored: the client's tier's ({@code approval_limit_<tier>} setting)
401:     * when its tier has one, else the workspace's ({@code approval_limit} setting); null when neither is set.
403:    @Formula("(SELECT COALESCE((SELECT t.setting_value FROM app_setting t, client c WHERE c.id = client_id AND t.name = 'approval_limit_' || c.tier),"
404:            + " (SELECT s.setting_value FROM app_setting s WHERE s.name = 'approval_limit')))")
405:    private String approvalLimitUsd;
518:     * Whether the approval limit is halved because the client is a MEDIUM payment risk (see
519:     * {@link #halveApprovalLimit}); not stored, worked out again each time the invoice is read.
522:    private boolean approvalLimitHalved;
525:     * Whether the client is a HIGH payment risk, so the draft needs two approvals whatever its size (see
910:    /** Whether the discount takes off more than a fifth of the subtotal, after any cap, and so needs approval. */
1319:    /** Whether an invoice needs approval before it is sent, has been approved, or needs none. */
1320:    public enum Approval {
1321:        NOT_NEEDED, NEEDS_APPROVAL, APPROVED
1325:     * The grand total above which a draft needs approval: the approval limit (the client tier's, else the workspace's) in US dollars
1329:    private BigDecimal approvalLimit() {
1330:        if (approvalLimitUsd == null) {
1333:        BigDecimal usd = new BigDecimal(approvalLimitUsd.trim());
1334:        if (approvalLimitHalved) {
1340:    /** Halves the approval limit (or restores it): a MEDIUM payment risk client has half the limit. */
1341:    public void halveApprovalLimit(boolean halved) {
1342:        this.approvalLimitHalved = halved;
1345:    /** Marks the client as a HIGH payment risk (or not): every draft of such a client needs two approvals. */
1351:     * The total a draft is judged and approved on at the tax rate: the plan total (with its interest and plan fee)
1354:    public BigDecimal approvalTotal(BigDecimal taxRate) {
1358:    /** The number of days an approval stays good after the day it was given: as many as the client's tier allows. */
1359:    public int approvalDays() {
1361:        return (tier == null ? ClientTier.STANDARD : tier).approvalDays();
1365:     * The invoice's approval at the tax rate as of today, judged on its {@link #approvalTotal}: a credit note, or an invoice whose grand total
1366:     * (before any withholding) is not over the approval limit and whose discount takes off no more than a
1367:     * fifth of the subtotal, needs none; otherwise it is approved while its grand total is exactly the total
1368:     * it was approved at and no more than {@link #approvalDays} days have passed since it was approved.
1369:     * Once sent, an invoice is as it was approved. Every draft of a client with a HIGH payment risk (highRisk)
1370:     * needs approval, whatever its size, as does every draft that would take its client over its credit limit
1371:     * (overCreditLimit). A draft whose grand total is more than one and a half times the approval limit, or
1372:     * of a HIGH payment risk client, needs {@link #approvalsRequired two approvals} of that same total.
